```python
def longest_palindrome(s):
    res = ""
    for i in range(len(s)):
        for j in range(i, len(s)):
            substr = s[i:j+1]
            if substr == substr[::-1] and len(substr) > len(res):
                res = substr
    return res
```

```python
def remove_duplicates(sentence):
    seen = set()
    result = []
    for word in sentence.split():
        if word not in seen:
            seen.add(word)
            result.append(word)
    return ' '.join(result)
```

