```python
def caesar_encrypt(msg, shift):
    res = ''
    for c in msg:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            res += chr((ord(c) - base + shift) % 26 + base)
        else:
            res += c
    return res
```

